-- ==========================================
-- FILE: 007_run_ghosts_guard.sql
-- ==========================================
-- Bounds on client-written ghost rows (rival ghosts + live race state).
--
-- run_ghosts stays writable by authenticated clients because friend races
-- upsert it every 3 seconds (js/game.js startFriendRacePolling) and the
-- submit-score rate limit would break them. The payload can no longer be
-- unbounded, though: a client used to be able to push a 500,000 score or an
-- arbitrarily large timeline/meta straight through PostgREST.

create or replace function public.guard_run_ghost()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  samples int;
begin
  if char_length(new.mode) < 1 or char_length(new.mode) > 32 then
    raise exception 'run_ghosts.mode length';
  end if;
  if char_length(new.run_key) < 1 or char_length(new.run_key) > 64 then
    raise exception 'run_ghosts.run_key length';
  end if;
  if new.best_score < 0 or new.best_score > 500000 then
    raise exception 'run_ghosts.best_score range';
  end if;
  if jsonb_typeof(new.timeline) <> 'object' then
    raise exception 'run_ghosts.timeline shape';
  end if;
  if new.timeline ? 'samples' then
    if jsonb_typeof(new.timeline -> 'samples') <> 'array' then
      raise exception 'run_ghosts.timeline samples shape';
    end if;
    samples := jsonb_array_length(new.timeline -> 'samples');
    if samples > 2000 then
      raise exception 'run_ghosts.timeline samples';
    end if;
  end if;
  if pg_column_size(new.timeline) > 131072 then
    raise exception 'run_ghosts.timeline size';
  end if;
  if jsonb_typeof(new.meta) <> 'object' then
    raise exception 'run_ghosts.meta shape';
  end if;
  if pg_column_size(new.meta) > 8192 then
    raise exception 'run_ghosts.meta size';
  end if;
  return new;
end;
$$;

drop trigger if exists run_ghosts_guard on public.run_ghosts;
create trigger run_ghosts_guard
  before insert or update on public.run_ghosts
  for each row execute function public.guard_run_ghost();

revoke all on function public.guard_run_ghost() from public;
revoke all on function public.guard_run_ghost() from anon, authenticated;

notify pgrst, 'reload schema';

-- ==========================================
-- FILE: 008_abuse_guards.sql
-- ==========================================
-- Abuse guards from the 2026-11 backend audit. Apply after 007_run_ghosts_guard.sql. Safe to re-run.
--
-- 1. run_ghosts: a signed-in client could still write unlimited rows (own-row
--    RLS, a client-chosen run_key, up to ~128 KB of timeline each). Row counts
--    are now capped per user and the key formats are fixed.
-- 2. saves: 007 guarded ghosts but not the cloud save, which the client pushes
--    as one blob. The blob is now capped at 1 MiB.
-- 3. score_submission_log: one row per submission, rejected ones included,
--    forever. Rows older than 30 days are pruned daily.

-- ---------------------------------------------------------------------------
-- 1. run_ghosts: key formats and a per-user row cap
-- ---------------------------------------------------------------------------
-- Keys the game really writes: modes trial / pilgrimage / blitz / live; run keys
-- "campaign", "blitz", "site:<id>", a five-character room code, and the
-- "<edition>~<key>" form of the old daily ghosts.

create or replace function public.guard_run_ghost()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  samples int;
begin
  if char_length(new.mode) < 1 or char_length(new.mode) > 32 then
    raise exception 'run_ghosts.mode length';
  end if;
  if new.mode !~ '^[a-z][a-z0-9-]*$' then
    raise exception 'run_ghosts.mode format';
  end if;
  if char_length(new.run_key) < 1 or char_length(new.run_key) > 64 then
    raise exception 'run_ghosts.run_key length';
  end if;
  if new.run_key !~ '^[A-Za-z0-9:~._-]+$' then
    raise exception 'run_ghosts.run_key format';
  end if;
  if new.best_score < 0 or new.best_score > 500000 then
    raise exception 'run_ghosts.best_score range';
  end if;
  if jsonb_typeof(new.timeline) <> 'object' then
    raise exception 'run_ghosts.timeline shape';
  end if;
  if new.timeline ? 'samples' then
    if jsonb_typeof(new.timeline -> 'samples') <> 'array' then
      raise exception 'run_ghosts.timeline samples shape';
    end if;
    samples := jsonb_array_length(new.timeline -> 'samples');
    if samples > 2000 then
      raise exception 'run_ghosts.timeline samples';
    end if;
  end if;
  if pg_column_size(new.timeline) > 131072 then
    raise exception 'run_ghosts.timeline size';
  end if;
  if jsonb_typeof(new.meta) <> 'object' then
    raise exception 'run_ghosts.meta shape';
  end if;
  if pg_column_size(new.meta) > 8192 then
    raise exception 'run_ghosts.meta size';
  end if;
  return new;
end;
$$;

-- Deletes a user's oldest ghosts beyond the cap instead of rejecting the new one,
-- because every Pilgrimage site and every friend-race room is a new key and a
-- long-time player must keep saving ghosts. SECURITY DEFINER because clients
-- have no DELETE grant. The row just written always survives, so a device with a
-- wrong clock cannot delete its own new ghost.
create or replace function public.trim_run_ghosts()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  per_mode_cap int;
  total_cap constant int := 100;
begin
  per_mode_cap := case new.mode when 'pilgrimage' then 64 else 8 end;

  delete from public.run_ghosts
  where id in (
    select id from public.run_ghosts
    where user_id = new.user_id and mode = new.mode
    order by (id = new.id) desc, updated_at desc, id desc
    offset per_mode_cap
  );

  delete from public.run_ghosts
  where id in (
    select id from public.run_ghosts
    where user_id = new.user_id
    order by (id = new.id) desc, updated_at desc, id desc
    offset total_cap
  );

  return null;
end;
$$;

drop trigger if exists run_ghosts_trim on public.run_ghosts;
create trigger run_ghosts_trim
  after insert on public.run_ghosts
  for each row execute function public.trim_run_ghosts();

revoke all on function public.trim_run_ghosts() from public;
revoke all on function public.trim_run_ghosts() from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. saves: a size guard on the cloud save blob
-- ---------------------------------------------------------------------------
-- A save with a spaced-repetition card for every one of the 1,493 verses in the
-- banks measures about 224 KB as JSON text, so 1 MiB leaves a heavy player room
-- to grow while stopping a scripted account from storing megabytes per row.

create or replace function public.guard_save_payload()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if jsonb_typeof(new.payload) <> 'object' then
    raise exception 'saves.payload shape';
  end if;
  if pg_column_size(new.payload) > 1048576 then
    raise exception 'saves.payload size';
  end if;
  return new;
end;
$$;

drop trigger if exists saves_guard on public.saves;
create trigger saves_guard
  before insert or update on public.saves
  for each row execute function public.guard_save_payload();

revoke all on function public.guard_save_payload() from public;
revoke all on function public.guard_save_payload() from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. score_submission_log: prune after 30 days
-- ---------------------------------------------------------------------------
-- The rate limit looks back 10 minutes and the weekly audit 24 hours, so 30 days
-- is generous.

create index if not exists score_submission_log_created_idx
  on public.score_submission_log (created_at);

create or replace function public.prune_score_submission_log()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  removed integer;
begin
  delete from public.score_submission_log
  where created_at < now() - interval '30 days';
  get diagnostics removed = row_count;
  return removed;
end;
$$;

revoke all on function public.prune_score_submission_log() from public;
revoke all on function public.prune_score_submission_log() from anon, authenticated;

-- Runs daily when pg_cron is available (Supabase has it; enable it under
-- Database -> Extensions). Without it the migration still applies: run
-- `select public.prune_score_submission_log();` by hand now and then.
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule(
      'prune-score-submission-log',
      '17 3 * * *',
      'select public.prune_score_submission_log()'
    );
  else
    raise notice 'pg_cron is not available: schedule public.prune_score_submission_log() yourself';
  end if;
exception when others then
  raise notice 'pg_cron schedule skipped: %', sqlerrm;
end;
$$;

notify pgrst, 'reload schema';

-- ==========================================
-- FILE: 009_lock_trigger_functions.sql
-- ==========================================
-- Fix Supabase linter WARN: SECURITY DEFINER functions executable by anon/authenticated
-- Safe to run alone if 001 already applied.
-- Renamed from 002_lock_trigger_functions.sql: two migrations shared version 002, which the Supabase CLI
-- cannot apply. Every statement below is idempotent, so a project that already ran it under the old name can
-- run it again unchanged.
-- Lints: 0028_anon_security_definer_function_executable
--        0029_authenticated_security_definer_function_executable

-- Timestamp trigger does not need elevated privileges
create or replace function public.touch_save_server_time()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.server_updated_at := now();
  return new;
end;
$$;

-- Signup trigger must stay DEFINER (inserts profiles/saves during auth.users insert)
-- but must NOT be callable as RPC by clients
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  base text;
  candidate text;
  n int := 0;
begin
  base := coalesce(
    nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''),
    'Pilgrim-' || upper(substr(replace(new.id::text, '-', ''), 1, 4))
  );
  if char_length(base) < 2 then
    base := 'Pilgrim';
  end if;
  candidate := left(base, 32);

  while exists (
    select 1 from public.profiles p where lower(p.display_name) = lower(candidate)
  ) loop
    n := n + 1;
    candidate := left(base, 28) || '-' || n::text;
  end loop;

  insert into public.profiles (id, display_name)
  values (new.id, candidate)
  on conflict (id) do nothing;

  insert into public.saves (user_id, payload, revision)
  values (new.id, '{}'::jsonb, 1)
  on conflict (user_id) do nothing;

  return new;
end;
$$;

revoke all on function public.handle_new_user() from public;
revoke all on function public.handle_new_user() from anon, authenticated;
revoke all on function public.touch_save_server_time() from public;
revoke all on function public.touch_save_server_time() from anon, authenticated;

notify pgrst, 'reload schema';

-- ==========================================
-- FILE: 010_tip_jar.sql
-- ==========================================
-- The tip jar's numbers, kept by hand on the admin page (admin.html). Apply after 009. Safe to re-run.
--
-- Nothing here reads PayPal: the owner types in what has really arrived. One row holds the raised total and the
-- goal, anyone may read it (the menu's Tip Jar shows it), and only accounts in site_admins may change it.

create table if not exists public.tip_jar (
  id smallint primary key default 1,
  raised_usd numeric(10, 2) not null default 0,
  goal_usd numeric(10, 2) not null default 100,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id) on delete set null,
  constraint tip_jar_single_row check (id = 1),
  constraint tip_jar_raised_range check (raised_usd >= 0 and raised_usd <= 1000000),
  constraint tip_jar_goal_range check (goal_usd >= 1 and goal_usd <= 1000000)
);

insert into public.tip_jar (id) values (1) on conflict (id) do nothing;

-- Who changed it and when comes from the server, not from the request, so neither can be written by hand.
create or replace function public.touch_tip_jar()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end;
$$;

drop trigger if exists tip_jar_touch on public.tip_jar;
create trigger tip_jar_touch
  before insert or update on public.tip_jar
  for each row execute function public.touch_tip_jar();

revoke all on function public.touch_tip_jar() from public;
revoke all on function public.touch_tip_jar() from anon, authenticated;

alter table public.tip_jar enable row level security;

drop policy if exists "tip jar readable" on public.tip_jar;
create policy "tip jar readable"
  on public.tip_jar for select
  to anon, authenticated
  using (true);

drop policy if exists "owner update tip jar" on public.tip_jar;
create policy "owner update tip jar"
  on public.tip_jar for update
  to authenticated
  using (public.is_site_admin())
  with check (public.is_site_admin());

-- Postgres checks table privileges before RLS, so these grants are what make the policy reachable.
-- Supabase gives every new table all privileges for anon and authenticated by default, including TRUNCATE (which
-- row-level security does not cover), so everything is taken away first and only what is needed is given back.
-- There is no insert or delete for clients: the one row is created above.
revoke all on table public.tip_jar from anon, authenticated;
grant select on table public.tip_jar to anon, authenticated, service_role;
grant update (raised_usd, goal_usd) on table public.tip_jar to authenticated;
grant insert, update on table public.tip_jar to service_role;

notify pgrst, 'reload schema';

-- ==========================================
-- FILE: 011_revoke_default_truncate.sql
-- ==========================================
-- Takes TRUNCATE, REFERENCES and TRIGGER away from the API roles on every public table. Apply after 010. Safe to re-run.
--
-- Supabase gives anon and authenticated every table privilege on each new table in public, and the earlier
-- migrations only revoked insert, update and delete where they cared. TRUNCATE is the one that matters: row-level
-- security does not apply to it, so a role holding it could empty a table whatever the policies say. The app's API
-- (PostgREST) offers no way to run TRUNCATE, so this is not reachable through the game today. It is still not a
-- privilege a browser role should hold, and REFERENCES and TRIGGER are not used by any client either.
--
-- SELECT, INSERT, UPDATE and DELETE are left exactly as each migration set them, and service_role is untouched.

do $$
declare
  t record;
begin
  for t in
    select c.relname
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p')
  loop
    execute format('revoke truncate, references, trigger on table public.%I from anon, authenticated', t.relname);
  end loop;
end;
$$;

-- A table created from now on by the role that runs migrations and the SQL Editor (postgres) starts the same way, so
-- the next migration does not have to remember. Supabase keeps a second default for tables made by its own
-- supabase_admin role; that one is not ours to change, and no migration or SQL Editor query creates tables as it.
alter default privileges in schema public
  revoke truncate, references, trigger on tables from anon, authenticated;

notify pgrst, 'reload schema';

-- ==========================================
-- FILE: 20260901104635_blitz_best_only.sql
-- ==========================================
delete from public.blitz_scores a
using public.blitz_scores b
where a.user_id = b.user_id
  and (
    a.score < b.score
    or (a.score = b.score and a.survived_ms < b.survived_ms)
    or (a.score = b.score and a.survived_ms = b.survived_ms and a.created_at < b.created_at)
    or (a.score = b.score and a.survived_ms = b.survived_ms and a.created_at = b.created_at and a.id < b.id)
  );

drop index if exists public.blitz_scores_user_uidx;
create unique index blitz_scores_user_uidx on public.blitz_scores (user_id);

notify pgrst, 'reload schema';
